INSERT OR IGNORE INTO diagnostic_question_bank (id, test_type, section, topic, question, options, correct_answer, explanation, difficulty, is_active, source) VALUES (1000, 'TOEFL_IBT', 'reading', 'detail', 'What is indicated about Mr. Walther''s appointment?', '[{"text":"Mr. Walther''s appointment has been rescheduled to a later date at his request.","is_answer":false},{"text":"The appointment will take all day due to the extensive tests being conducted.","is_answer":false},{"text":"The office will be crowded during Mr. Walther''s appointment because of multiple patients.","is_answer":false},{"text":"Mr. Walther''s exam will involve a full battery of tests, making it longer than usual.","is_answer":false}]', 'Mr. Walther''s exam will involve a full battery of tests, making it longer than usual.', 'Pulled from test_contents id=22', 4, 1, 'test_contents');
INSERT OR IGNORE INTO diagnostic_question_bank (id, test_type, section, topic, question, options, correct_answer, explanation, difficulty, is_active, source) VALUES (1001, 'TOEFL_IBT', 'reading', 'main_idea', 'The word "burgeoning" in the first paragraph is closest in meaning to', '[{"text":"The citrus industry in Florida was declining due to lack of rail connections.","is_answer":false},{"text":"The citrus industry in Florida was developing rapidly during the early 1900s.","is_answer":false},{"text":"The citrus industry in Florida was promoting its products through advertisements.","is_answer":false},{"text":"The citrus industry in Florida was established in the early 1800s.","is_answer":false}]', 'The citrus industry in Florida was developing rapidly during the early 1900s.', 'Pulled from test_contents id=734', 4, 1, 'test_contents');
INSERT OR IGNORE INTO diagnostic_question_bank (id, test_type, section, topic, question, options, correct_answer, explanation, difficulty, is_active, source) VALUES (1002, 'TOEFL_IBT', 'reading', 'detail', 'What will happen on Tuesday?', '[{"text":"The CEO will hold a press conference on Tuesday, November 27th at 10:30 AM in the Rutger Tower auditorium.","is_answer":false},{"text":"The press conference will be held at the downtown city hall on Wednesday, November 28th at 10:30 AM.","is_answer":false},{"text":"Ms. Ogilvie will issue a written statement regarding her promotion and the future course of the company.","is_answer":false},{"text":"Mr. Carruthers will send an email to Ms. Zeelander on Tuesday regarding the press conference.","is_answer":false}]', 'The CEO will hold a press conference on Tuesday, November 27th at 10:30 AM in the Rutger Tower auditorium.', 'Pulled from test_contents id=538', 4, 1, 'test_contents');
INSERT OR IGNORE INTO diagnostic_question_bank (id, test_type, section, topic, question, options, correct_answer, explanation, difficulty, is_active, source) VALUES (1003, 'TOEFL_IBT', 'listening', 'detail', '<p><span style="background-color:transparent;color:#000000;"><strong>What is the purpose of the announcement?</strong></span></p>', '[{"text":"To announce an upcoming program","is_answer":false},{"text":"To report a schedule change","is_answer":false},{"text":"To introduce the keynote speaker","is_answer":false},{"text":"To greet attendees at an event","is_answer":false}]', 'To greet attendees at an event', 'Pulled from test_contents id=3083', 3, 1, 'test_contents');
INSERT OR IGNORE INTO diagnostic_question_bank (id, test_type, section, topic, question, options, correct_answer, explanation, difficulty, is_active, source) VALUES (1004, 'TOEFL_IBT', 'listening', 'main_idea', '<p><span style="background-color:transparent;color:#000000;"><strong>What does the woman say about Professor Grant?</strong></span></p>', '[{"text":"She has long lectures.","is_answer":false},{"text":"She gives a lot of extra credit.","is_answer":false},{"text":"She grades very strictly.","is_answer":false},{"text":"She often cancels class.","is_answer":false}]', 'She grades very strictly.', 'Pulled from test_contents id=3430', 3, 1, 'test_contents');
INSERT OR IGNORE INTO diagnostic_question_bank (id, test_type, section, topic, question, options, correct_answer, explanation, difficulty, is_active, source) VALUES (1005, 'TOEFL_IBT', 'listening', 'main_idea', '<p><span style="background-color:transparent;color:#000000;"><strong>What did the woman do during her shadowing?</strong></span></p>', '[{"text":"Organized patient records","is_answer":false},{"text":"Observed some exercises ","is_answer":false},{"text":"Cleaned the therapy equipment","is_answer":false},{"text":"Worked at the front desk","is_answer":false}]', 'Observed some exercises ', 'Pulled from test_contents id=3294', 3, 1, 'test_contents');
INSERT OR IGNORE INTO diagnostic_question_bank (id, test_type, section, topic, question, options, correct_answer, explanation, difficulty, is_active, source) VALUES (1006, 'TOEFL_IBT', 'listening', 'function', 'Woman: Can’t I reserve a table in the cafeteria?', '[{"text":"I’ve just been there.","is_answer":false},{"text":"It’s first come, first served.","is_answer":false},{"text":"There are vegetarian options.","is_answer":false},{"text":"Up these stairs, on your left.","is_answer":false}]', 'It’s first come, first served.', 'Pulled from test_contents id=3256', 4, 1, 'test_contents');
INSERT OR IGNORE INTO diagnostic_question_bank (id, test_type, section, topic, question, options, correct_answer, explanation, difficulty, is_active, source) VALUES (1007, 'TOEFL_IBT', 'listening', 'function', 'Woman: Sam can give us a ride to the festival.', '[{"text":"That’s wonderful news. ","is_answer":false},{"text":"A variety of musicians.","is_answer":false},{"text":"We had a great time.","is_answer":false},{"text":"About a two-hour drive.","is_answer":false}]', 'That’s wonderful news. ', 'Pulled from test_contents id=3402', 4, 1, 'test_contents');
INSERT OR IGNORE INTO diagnostic_question_bank (id, test_type, section, topic, question, options, correct_answer, explanation, difficulty, is_active, source) VALUES (1008, 'TOEFL_IBT', 'listening', 'main_idea', '<p><span style="background-color:transparent;color:#000000;"><strong>What is the speaker discussing?</strong></span></p>', '[{"text":"The evolution of gut bacteria in humans over time","is_answer":false},{"text":"The connection between gut bacteria and mood","is_answer":false},{"text":"The dangers of gut bacteria to the immune system","is_answer":false},{"text":"The movement of gut bacteria through the digestive tract","is_answer":false}]', 'The connection between gut bacteria and mood', 'Pulled from test_contents id=3331', 4, 1, 'test_contents');
INSERT OR IGNORE INTO diagnostic_question_bank (id, test_type, section, topic, question, options, correct_answer, explanation, difficulty, is_active, source) VALUES (1009, 'TOEFL_ITP', 'grammar', 'subject_verb', '___ have settled, one of their first concerns has been to locate an adequate water supply.', '[{"text":"Wherever people","is_answer":false},{"text":"There are people who","is_answer":false},{"text":"Whether people","is_answer":false},{"text":"People","is_answer":false}]', 'Wherever people', 'Pulled from test_contents id=4061', 3, 1, 'test_contents');
INSERT OR IGNORE INTO diagnostic_question_bank (id, test_type, section, topic, question, options, correct_answer, explanation, difficulty, is_active, source) VALUES (1010, 'TOEFL_ITP', 'grammar', 'subject_verb', '. Sharp knives are actually safer to use___', '[{"text":"as dull ones","is_answer":false},{"text":"as ones that are dull","is_answer":false},{"text":"than dull ones","is_answer":false},{"text":"that are dull ones","is_answer":false}]', 'than dull ones', 'Pulled from test_contents id=4107', 3, 1, 'test_contents');
