INSERT OR IGNORE INTO diagnostic_question_bank (id, test_type, section, topic, question, options, correct_answer, explanation, difficulty, is_active, source) VALUES (1012, 'TOEFL_ITP', 'grammar', 'error_identification', 'Identify the error in the following sentence: The new laboratory equipment is (A)much more (B)efficient (C)as the (D)previous model.', '[{"text":"A","is_answer":false},{"text":"B","is_answer":false},{"text":"C","is_answer":true},{"text":"D","is_answer":false}]', 'C', 'Pulled from test_contents id=4576', 4, 1, 'test_contents');
